var TRUTHY_ENV_VALUES = new Set(["1", "true", "yes", "y", "on", "enabled"]);
function isTruthyEnvValue(value) {
  if (typeof value !== "string")
    return false;
  const normalized = value.trim().toLowerCase();
  if (!normalized)
    return false;
  return TRUTHY_ENV_VALUES.has(normalized);
}

