var MAX_LONG_TERM_MEMORY_TEXT_LENGTH = 5000;
var MAX_LONG_TERM_MEMORY_CATEGORIES = 10;
var longTermMemoryProvider = {
  name: "LONG_TERM_MEMORY",
  description: "Persistent facts and preferences about the user",
  position: 50,
  contexts: ["general"],
  contextGate: { anyOf: ["general"] },
  cacheStable: false,
  cacheScope: "turn",
  roleGate: { minRole: "USER" },
  get: async (runtime2, message, _state) => {
    try {
      const memoryService = runtime2.getService("memory");
      if (!memoryService) {
        return {
          data: { memoryCount: 0 },
          values: { longTermMemories: "" },
          text: ""
        };
      }
      const { entityId } = message;
      if (entityId === runtime2.agentId) {
        return {
          data: { memoryCount: 0 },
          values: { longTermMemories: "" },
          text: ""
        };
      }
      const memories = await memoryService.getLongTermMemories(entityId, undefined, 25);
      if (memories.length === 0) {
        logAdvancedMemoryTrajectory({
          runtime: runtime2,
          message,
          providerName: "LONG_TERM_MEMORY",
          purpose: "long_term_memory",
          data: {
            memoryCount: 0,
            categoryCount: 0
          },
          query: {
            entityId
          }
        });
        return {
          data: { memoryCount: 0 },
          values: { longTermMemories: "" },
          text: ""
        };
      }
      const formattedMemories = formatLongTermMemories(memories);
      const trimmedFormattedMemories = formattedMemories.length > MAX_LONG_TERM_MEMORY_TEXT_LENGTH ? `${formattedMemories.slice(0, MAX_LONG_TERM_MEMORY_TEXT_LENGTH)}...` : formattedMemories;
      const text = addHeader("# What I Know About You", trimmedFormattedMemories);
      const categoryCounts = new Map;
      for (const memory2 of memories) {
        const count = categoryCounts.get(memory2.category) || 0;
        categoryCounts.set(memory2.category, count + 1);
      }
      const categoryList = Array.from(categoryCounts.entries()).slice(0, MAX_LONG_TERM_MEMORY_CATEGORIES).map(([cat, count]) => `${cat}: ${count}`).join(", ");
      logAdvancedMemoryTrajectory({
        runtime: runtime2,
        message,
        providerName: "LONG_TERM_MEMORY",
        purpose: "long_term_memory",
        data: {
          memoryCount: memories.length,
          categoryCount: categoryCounts.size
        },
        query: {
          entityId
        }
      });
      return {
        data: {
          memoryCount: memories.length,
          categories: categoryList,
          truncated: formattedMemories.length > MAX_LONG_TERM_MEMORY_TEXT_LENGTH
        },
        values: {
          longTermMemories: text,
          memoryCategories: categoryList
        },
        text
      };
    } catch (error51) {
      const err = error51 instanceof Error ? error51.message : String(error51);
      logger.error({ src: "provider:memory", err }, "Error in longTermMemoryProvider");
      return {
        data: {
          memoryCount: 0,
          error: err
        },
        values: { longTermMemories: "" },
        text: ""
      };
    }
  }
};

