      const historyStart = sortedMessages.length > MAX_ADMIN_HISTORY_MESSAGES ? sortedMessages.length - MAX_ADMIN_HISTORY_MESSAGES : 0;
      const historyMessages = sortedMessages.slice(historyStart);
