// src/features/documents/bm25.ts
function tokenize(text) {
  return text.toLowerCase().replace(/[^a-z0-9\s]/g, " ").split(/\s+/).filter((t) => t.length > 0);
}
function bm25Scores(query, documents2, opts) {
  const k1 = opts?.k1 ?? 1.5;
  const b = opts?.b ?? 0.75;
  if (documents2.length === 0 || !query.trim()) {
    return documents2.map((doc2) => ({ id: doc2.id, score: 0 }));
  }
  const queryTerms = tokenize(query);
  if (queryTerms.length === 0) {
    return documents2.map((doc2) => ({ id: doc2.id, score: 0 }));
  }
  const tokenizedDocs = documents2.map((doc2) => tokenize(doc2.text));
  const totalLength = tokenizedDocs.reduce((sum, toks) => sum + toks.length, 0);
  const avgDocLength = totalLength / documents2.length;
  const docFreq = new Map;
  for (const toks of tokenizedDocs) {
    const seen = new Set;
    for (const tok of toks) {
      if (!seen.has(tok)) {
        seen.add(tok);
        docFreq.set(tok, (docFreq.get(tok) ?? 0) + 1);
      }
    }
  }
  const N = documents2.length;
  return tokenizedDocs.map((toks, docIndex) => {
    const docLength = toks.length;
    const termFreq = new Map;
    for (const tok of toks) {
      termFreq.set(tok, (termFreq.get(tok) ?? 0) + 1);
    }
    let score = 0;
    for (const term of queryTerms) {
      const tf = termFreq.get(term) ?? 0;
      if (tf === 0)
        continue;
      const df = docFreq.get(term) ?? 0;
      const idf = Math.log((N - df + 0.5) / (df + 0.5) + 1);
      const tfNorm = tf * (k1 + 1) / (tf + k1 * (1 - b + b * (docLength / avgDocLength)));
      score += idf * tfNorm;
    }
    return { id: documents2[docIndex].id, score };
  });
}
function normalizeBm25Scores(scores) {
  const maxScore = Math.max(...scores.map((s) => s.score));
  if (maxScore === 0)
    return scores;
  return scores.map((s) => ({ id: s.id, score: s.score / maxScore }));
}

