function filterInMemory(messages, filters2) {
  const contentLower = filters2.content?.toLowerCase().trim();
  const senderId = filters2.sender?.identifier?.toLowerCase();
  const senderName = filters2.sender?.displayName?.toLowerCase();
  const worlds = filters2.worldIds && new Set(filters2.worldIds);
  const channels = filters2.channelIds && new Set(filters2.channelIds);
  const wantedTags = filters2.tags ?? [];
  const sinceMs = filters2.sinceMs;
  const untilMs = filters2.untilMs;
  const out = [];
  for (const m of messages) {
    if (filters2.sources && !filters2.sources.includes(m.source))
      continue;
    if (worlds && (!m.worldId || !worlds.has(m.worldId)))
      continue;
    if (channels && (!m.channelId || !channels.has(m.channelId)))
      continue;
    if (sinceMs !== undefined && m.receivedAtMs < sinceMs)
      continue;
    if (untilMs !== undefined && m.receivedAtMs > untilMs)
      continue;
    if (senderId && m.from.identifier.toLowerCase() !== senderId)
      continue;
    if (senderName) {
      const name = m.from.displayName?.toLowerCase();
      if (!name?.includes(senderName))
        continue;
    }
    if (wantedTags.length > 0) {
      const tags = m.tags ?? [];
      let allFound = true;
      for (const t of wantedTags) {
        if (!tags.includes(t)) {
          allFound = false;
          break;
        }
      }
      if (!allFound)
        continue;
    }
    if (contentLower) {
      const haystack = `${m.subject ?? ""} ${m.snippet} ${m.body ?? ""}`.toLowerCase();
      if (!haystack.includes(contentLower))
        continue;
    }
    out.push(m);
  }
  return out;
}

