var MAX_MESSAGES = 5000;
var MAX_DRAFTS = 2000;
function capMap(map2, max) {
  while (map2.size > max) {
    const oldest = map2.keys().next().value;
    if (oldest === undefined)
      break;
    map2.delete(oldest);
  }
}

class MessageRefStore {
  messages = new Map;
  drafts = new Map;
  saveMessage(ref) {
    this.messages.set(ref.id, ref);
    capMap(this.messages, MAX_MESSAGES);
  }
  saveMessages(refs) {
    for (const r of refs)
      this.messages.set(r.id, r);
    capMap(this.messages, MAX_MESSAGES);
  }
  getMessage(id) {
    return this.messages.get(id) ?? null;
  }
  findByExternalId(source, externalId) {
    for (const m of this.messages.values()) {
      if (m.source === source && m.externalId === externalId)
        return m;
    }
    return null;
  }
  addTag(messageId, tag) {
    const existing = this.messages.get(messageId);
    if (!existing)
      return null;
    const tags = existing.tags ? [...existing.tags] : [];
    if (!tags.includes(tag))
      tags.push(tag);
    const next = { ...existing, tags };
    this.messages.set(messageId, next);
    return next;
  }
  removeTag(messageId, tag) {
    const existing = this.messages.get(messageId);
    if (!existing)
      return null;
    if (!existing.tags || existing.tags.length === 0)
      return existing;
    const tags = existing.tags.filter((t) => t !== tag);
    const next = { ...existing, tags };
    this.messages.set(messageId, next);
    return next;
  }
  saveDraft(record2) {
    this.drafts.set(record2.draftId, record2);
    capMap(this.drafts, MAX_DRAFTS);
  }
  getDraft(draftId) {
    return this.drafts.get(draftId) ?? null;
  }
  markDraftSent(draftId, externalId) {
    const existing = this.drafts.get(draftId);
    if (!existing)
      return null;
    const next = {
      ...existing,
      sent: true,
      sentExternalId: externalId
    };
    this.drafts.set(draftId, next);
    return next;
  }
  markDraftScheduled(draftId, sendAtMs, scheduledId) {
    const existing = this.drafts.get(draftId);
    if (!existing)
      return null;
    const next = {
      ...existing,
      scheduledForMs: sendAtMs,
      scheduledId
    };
    this.drafts.set(draftId, next);
    return next;
  }
  listMessages() {
    return Array.from(this.messages.values());
  }
  clear() {
    this.messages.clear();
    this.drafts.clear();
  }
}
