// src/security/pii-scrub-markers.ts
var PII_SCRUB_MARKER_PREFIX = "pii";
function hashScrubContent(content) {
  return createHash3("sha256").update(content).digest("hex");
}
function scrubMarkerKey(contentHash, rulesetVersion) {
  if (typeof rulesetVersion !== "string" || rulesetVersion.length === 0) {
    throw new Error("[pii-scrub-markers] rulesetVersion must be a non-empty string; refusing to build a version-collapsed marker key");
  }
  if (typeof contentHash !== "string" || contentHash.length === 0) {
    throw new Error("[pii-scrub-markers] contentHash must be a non-empty string");
  }
  return `${PII_SCRUB_MARKER_PREFIX}:${contentHash}:v${rulesetVersion}`;
}
function scrubMarkerKeyForContent(content, rulesetVersion) {
  return scrubMarkerKey(hashScrubContent(content), rulesetVersion);
}
async function isScrubDone(cache, content, rulesetVersion) {
  const key = scrubMarkerKeyForContent(content, rulesetVersion);
  const marker = await cache.getCache(key);
  return marker !== undefined && marker !== null;
}
async function markScrubDone(cache, content, marker) {
  const contentHash = hashScrubContent(content);
  const key = scrubMarkerKey(contentHash, marker.rulesetVersion);
  const record2 = {
    contentHash,
    rulesetVersion: marker.rulesetVersion,
    modelId: marker.modelId,
    tier0Only: marker.tier0Only,
    completedAt: marker.completedAt ?? Date.now()
  };
  return cache.setCache(key, record2);
}
async function getScrubMarker(cache, content, rulesetVersion) {
  const key = scrubMarkerKeyForContent(content, rulesetVersion);
  const marker = await cache.getCache(key);
  return marker ?? undefined;
}

