var BIP39_WORD_SET = new Set(BIP39_WORDLIST);
var BIP39_WORD_INDEX = new Map(BIP39_WORDLIST.map((w, i) => [w, i]));
var VALID_WORD_COUNTS = new Set([12, 15, 18, 21, 24]);
function mnemonicValid(phrase) {
  const words = phrase.trim().toLowerCase().split(/\s+/);
  if (!VALID_WORD_COUNTS.has(words.length))
    return false;
  let bits = "";
  for (const word of words) {
    const index = BIP39_WORD_INDEX.get(word);
    if (index === undefined)
      return false;
    bits += index.toString(2).padStart(11, "0");
  }
  const totalBits = words.length * 11;
  const checksumBits = totalBits / 33;
  const entropyBits = totalBits - checksumBits;
  const entropy = bits.slice(0, entropyBits);
  const checksum = bits.slice(entropyBits);
  const entropyBytes = new Uint8Array(entropyBits / 8);
  for (let i = 0;i < entropyBytes.length; i += 1) {
    entropyBytes[i] = Number.parseInt(entropy.slice(i * 8, i * 8 + 8), 2);
  }
  const hash2 = createHash3("sha256").update(entropyBytes).digest();
  let hashBits = "";
  for (let i = 0;i < Math.ceil(checksumBits / 8); i += 1) {
    hashBits += (hash2[i] ?? 0).toString(2).padStart(8, "0");
  }
  return hashBits.slice(0, checksumBits) === checksum;
}
function findAllMnemonicPhrases(text) {
  const tokens = [...text.matchAll(/[a-zA-Z]{3,8}/g)];
  const spans = [];
  let i = 0;
  while (i < tokens.length) {
    let matched = false;
    for (const count of [24, 21, 18, 15, 12]) {
      if (i + count > tokens.length)
        continue;
      let adjacent = true;
      for (let j = i + 1;j < i + count; j += 1) {
        const prev = tokens[j - 1];
        const cur = tokens[j];
        const gapStart = (prev.index ?? 0) + prev[0].length;
        if (!/^\s+$/.test(text.slice(gapStart, cur.index ?? 0))) {
          adjacent = false;
          break;
        }
      }
      if (!adjacent)
        continue;
      const phrase = tokens.slice(i, i + count).map((t) => t[0].toLowerCase()).join(" ");
      if (mnemonicValid(phrase)) {
        const first = tokens[i];
        const last = tokens[i + count - 1];
        const start = first.index ?? 0;
        const end = (last.index ?? 0) + last[0].length;
        spans.push({ value: text.slice(start, end), start, end });
        i += count;
        matched = true;
        break;
      }
    }
    if (!matched)
      i += 1;
  }
  return spans;
}

