async function persistCharacterPatch(runtime2, patch) {
  if (Object.keys(patch).length === 0) {
    return { success: true };
  }
  const previousCharacter = { ...runtime2.character };
  const previousName = typeof runtime2.character.name === "string" ? runtime2.character.name : undefined;
  const nextCharacter = {
    ...runtime2.character,
    ...patch
  };
  const persistenceService = getCharacterPersistenceService(runtime2);
  if (persistenceService) {
    const result2 = await persistenceService.persistCharacter({
      character: nextCharacter,
      previousCharacter,
      previousName,
      source: "agent"
    });
    if (!result2.success) {
      logger.warn({ error: result2.error }, "persistCharacterPatch: persistence service returned failure");
      return result2;
    }
  }
  Object.assign(runtime2.character, patch);
  return { success: true };
}

