function renderSlot(slot, header, footer) {
  const lines = [];
  if (slot.verbosity)
    lines.push(`- verbosity: ${slot.verbosity}`);
  if (slot.tone)
    lines.push(`- tone: ${slot.tone}`);
  if (slot.formality)
    lines.push(`- formality: ${slot.formality}`);
  if (slot.reply_gate && slot.reply_gate !== "always") {
    lines.push(`- reply_gate: ${slot.reply_gate}`);
  }
  if (slot.custom_directives.length > 0) {
    lines.push("- custom directives:");
    slot.custom_directives.forEach((directive, index) => {
      lines.push(`  ${index + 1}. ${directive}`);
    });
  }
  if (lines.length === 0)
    return null;
  const inferredTraits = Object.entries(slot.trait_sources).filter(([, source]) => source === "agent_inferred").map(([trait]) => trait);
  if (inferredTraits.length > 0 || slot.source === "agent_inferred") {
    const what = inferredTraits.length > 0 ? inferredTraits.join(", ") : "some of these";
    lines.push(`- provenance: ${what} inferred from conversation, not explicitly set; offer to adjust if the user objects`);
  }
  return [header, ...lines, footer].join(`
`);
}
