var missingSecretsProvider = {
  name: "MISSING_SECRETS",
  description: "Lists secrets that still need to be configured",
  dynamic: true,
  contexts: ["settings"],
  contextGate: { anyOf: ["settings"] },
  cacheStable: false,
  cacheScope: "turn",
  roleGate: { minRole: "ADMIN" },
  get: async (runtime2, message, _state) => {
    const room = await runtime2.getRoom(message.roomId);
    if (!room?.worldId) {
      return {
        data: { missing: [] },
        values: { missingSecrets: "" },
        text: ""
      };
    }
    const world = await runtime2.getWorld(room.worldId);
    if (!world?.metadata?.settings) {
      return {
        data: { missing: [] },
        values: { missingSecrets: "" },
        text: ""
      };
    }
    const settings2 = world.metadata.settings;
    const entries = Object.entries(settings2);
    const missingRequired = entries.filter(([_, s]) => s.required && s.value === null).map(([key, setting]) => ({
      key,
      name: setting.name,
      description: setting.usageDescription || setting.description
    }));
    const missingOptional = entries.filter(([_, s]) => !s.required && s.value === null).map(([key, setting]) => ({
      key,
      name: setting.name,
      description: setting.usageDescription || setting.description
    }));
    if (missingRequired.length === 0 && missingOptional.length === 0) {
      return {
        data: { missing: [] },
        values: { missingSecrets: "All secrets are configured." },
        text: "All secrets are configured."
      };
    }
    let output = "";
    if (missingRequired.length > 0) {
      output += `Missing required secrets:
${missingRequired.map((s) => `- ${s.key}: ${s.description}`).join(`
`)}

`;
    }
    if (missingOptional.length > 0) {
      output += `Missing optional secrets:
${missingOptional.map((s) => `- ${s.key}: ${s.description}`).join(`
`)}`;
    }
    return {
      data: {
        missing: [...missingRequired, ...missingOptional],
        missingRequired,
        missingOptional
      },
      values: { missingSecrets: output.trim() },
      text: output.trim()
    };
  }
};

