  const userText = (message.content.text ?? "").trim();
  const optionChoice = readStringOption2(options, "choice");
  const optionIntent = readStringOption2(options, "intent");
  const optionEditTarget = readStringOption2(options, "editTarget");
  const choiceText = explicitChoice ?? optionChoice ?? userText;
