// src/features/plugin-manager/actions/plugin-handlers/runtime-state.ts
function getPluginManager(runtime2) {
  return runtime2.getService("plugin_manager");
}
function normalizeName(value) {
  return value.trim().toLowerCase().replace(/^@elizaos\//, "").replace(/^plugin-/, "");
}
function matchesPluginName(candidate, requested) {
  const normalizedCandidate = normalizeName(candidate);
  const normalizedRequested = normalizeName(requested);
  return candidate === requested || normalizedCandidate === normalizedRequested || normalizedCandidate === normalizeName(`plugin-${requested}`) || candidate === `@elizaos/${requested}` || candidate === `@elizaos/plugin-${requested}` || candidate.endsWith(`/${requested}`) || candidate.endsWith(`/plugin-${requested}`);
}
function findPluginState(service2, nameOrId) {
  return service2.getAllPlugins().find((plugin2) => plugin2.id === nameOrId || matchesPluginName(plugin2.name, nameOrId));
}
function findPluginInfo(plugins, name) {
  return plugins.find((plugin2) => matchesPluginName(plugin2.name, name));
}
function summarizePluginState(plugin2) {
  const parts = [`${plugin2.name} [${plugin2.status}]`];
  if (plugin2.loadedAt) {
    parts.push(`loaded=${new Date(plugin2.loadedAt).toISOString()}`);
  }
  if (plugin2.unloadedAt) {
    parts.push(`unloaded=${new Date(plugin2.unloadedAt).toISOString()}`);
  }
  if (plugin2.error)
    parts.push(`error=${plugin2.error}`);
  return parts.join(" ");
}
async function runPluginStatus({
  runtime: runtime2,
  name,
  callback: callback2
}) {
  const service2 = getPluginManager(runtime2);
  if (!service2) {
    const text3 = "Plugin manager service not available";
    await callback2?.({ text: text3 });
    return { success: false, text: text3 };
  }
  const all = service2.getAllPlugins();
  const installed = await service2.listInstalledPlugins();
  const ejected = await service2.listEjectedPlugins();
  if (name) {
    const state2 = findPluginState(service2, name);
    const installedInfo = findPluginInfo(installed, name);
    const ejectedInfo = findPluginInfo(ejected, name);
    if (!state2 && !installedInfo && !ejectedInfo) {
      const text4 = `No plugin state found for ${name}.`;
      await callback2?.({ text: text4 });
      return {
        success: false,
        text: text4,
        values: { mode: "status", name, found: false }
      };
    }
    const lines = [
      `Plugin status for ${state2?.name ?? installedInfo?.name ?? ejectedInfo?.name ?? name}:`
    ];
    lines.push(state2 ? `  runtime: ${summarizePluginState(state2)}` : "  runtime: not registered");
    lines.push(installedInfo ? `  installed: yes (v${installedInfo.version}) at ${installedInfo.path}` : "  installed: no managed install found");
    lines.push(ejectedInfo ? `  ejected: yes (v${ejectedInfo.version}) at ${ejectedInfo.path}` : "  ejected: no");
    const text3 = lines.join(`
`);
    await callback2?.({ text: text3 });
    return {
      success: true,
      text: text3,
      values: {
        mode: "status",
        name,
        found: true,
        runtimeStatus: state2?.status,
        installed: Boolean(installedInfo),
        ejected: Boolean(ejectedInfo)
      },
      data: { state: state2, installed: installedInfo, ejected: ejectedInfo }
    };
  }
  const loadedCount = all.filter((plugin2) => plugin2.status === "loaded" /* LOADED */).length;
  const readyCount = all.filter((plugin2) => plugin2.status === "ready" /* READY */).length;
  const unloadedCount = all.filter((plugin2) => plugin2.status === "unloaded" /* UNLOADED */).length;
  const errorCount = all.filter((plugin2) => plugin2.status === "error" /* ERROR */).length;
  const text2 = [
    "Plugin status:",
    `  runtime total: ${all.length}`,
    `  loaded: ${loadedCount}`,
    `  ready: ${readyCount}`,
    `  unloaded: ${unloadedCount}`,
    `  errors: ${errorCount}`,
    `  managed installs: ${installed.length}`,
    `  ejected: ${ejected.length}`
  ].join(`
`);
  await callback2?.({ text: text2 });
  return {
    success: true,
    text: text2,
    values: {
      mode: "status",
      totalPlugins: all.length,
      loadedCount,
      readyCount,
      unloadedCount,
      errorCount,
      installedCount: installed.length,
      ejectedCount: ejected.length
    },
    data: { plugins: all, installed, ejected }
  };
}
