async function setPluginEnabled({
  runtime: runtime2,
  name,
  callback: callback2,
  enabled
}) {
  const service2 = getPluginManager(runtime2);
  if (!service2) {
    const text2 = "Plugin manager service not available";
    await callback2?.({ text: text2 });
    return { success: false, text: text2 };
  }
  if (!name) {
    const text2 = `Specify a plugin name to ${enabled ? "enable" : "disable"}.`;
    await callback2?.({ text: text2 });
    return { success: false, text: text2 };
  }
  const state2 = findPluginState(service2, name);
  if (!state2) {
    const text2 = `Plugin "${name}" is not registered in the current runtime.`;
    await callback2?.({ text: text2 });
    return { success: false, text: text2, values: { name, enabled } };
  }
  try {
    if (enabled) {
      await service2.loadPlugin({ pluginId: state2.id });
    } else {
      await service2.unloadPlugin({ pluginId: state2.id });
    }
    const updated = service2.getPlugin(state2.id);
    const text2 = `Plugin ${state2.name} ${enabled ? "enabled" : "disabled"} (${updated?.status ?? state2.status}).`;
    await callback2?.({ text: text2 });
    return {
      success: true,
      text: text2,
      values: {
        mode: enabled ? "enable" : "disable",
        name: state2.name,
        status: updated?.status ?? state2.status
      },
      data: { plugin: updated ?? state2 }
    };
  } catch (error51) {
    const message = error51 instanceof Error ? error51.message : String(error51);
    const text2 = `Failed to ${enabled ? "enable" : "disable"} ${state2.name}: ${message}`;
    await callback2?.({ text: text2 });
    return {
      success: false,
      text: text2,
      error: message,
      values: { name: state2.name, enabled }
    };
  }
}
async function runEnablePlugin(input) {
  return setPluginEnabled({ ...input, enabled: true });
}
async function runDisablePlugin(input) {
  return setPluginEnabled({ ...input, enabled: false });
}

