function computeSearchScore(plugin2, query) {
  const lq = query.toLowerCase();
  const terms = lq.split(/\s+/).filter((t) => t.length > 1);
  const ln = plugin2.name.toLowerCase();
  const ld = plugin2.description.toLowerCase();
  let score = 0;
  if (ln === lq || ln === `@elizaos/${lq}`)
    score += 100;
  else if (ln.includes(lq))
    score += 50;
  if (ld.includes(lq))
    score += 30;
  for (const t of plugin2.topics)
    if (t.toLowerCase().includes(lq))
      score += 25;
  for (const term of terms) {
    if (ln.includes(term))
      score += 15;
    if (ld.includes(term))
      score += 10;
    for (const t of plugin2.topics)
      if (t.toLowerCase().includes(term))
        score += 8;
  }
  if (score > 0) {
    if (plugin2.stars > 100)
      score += 5;
    if (plugin2.stars > 500)
      score += 5;
    if (plugin2.stars > 1000)
      score += 5;
  }
  return score;
}
