// src/features/plugin-manager/coreExtensions.ts
function extendRuntimeWithComponentUnregistration(runtime2) {
  const extendedRuntime = runtime2;
  if (!extendedRuntime.unregisterAction) {
    extendedRuntime.unregisterAction = function(actionName) {
      const index = this.actions.findIndex((a) => a.name === actionName);
      if (index !== -1) {
        this.actions.splice(index, 1);
        return true;
      }
      return false;
    };
  }
  if (!extendedRuntime.unregisterProvider) {
    extendedRuntime.unregisterProvider = function(providerName) {
      const index = this.providers.findIndex((p) => p.name === providerName);
      if (index !== -1) {
        this.providers.splice(index, 1);
      }
    };
  }
  if (!extendedRuntime.unregisterService) {
    extendedRuntime.unregisterService = async function(serviceType) {
      const services = this.getServicesByType(serviceType);
      if (services && services.length > 0) {
        for (const service2 of services) {
          await service2.stop();
        }
        const allServices = this.getAllServices();
        allServices.delete(serviceType);
      }
    };
  }
}
function applyRuntimeExtensions(runtime2) {
  extendRuntimeWithComponentUnregistration(runtime2);
}

