      await fs7.ensureDir(targetDir);
      const targetPkgPath = path8.join(targetDir, "package.json");
      if (!await fs7.pathExists(targetPkgPath)) {
        await fs7.writeJson(targetPkgPath, { private: true, dependencies: {} }, { spaces: 2 });
      }
