    assertSafeForShell(version3, "version", VALID_VERSION);
    const pm = await detectPackageManager();
    const spec25 = `${packageName}@${version3}`;
    onProgress?.({
      phase: "downloading",
      message: `Running ${pm} install ${spec25}...`
    });
    switch (pm) {
      case "bun":
        await execAsync2(`bun add ${spec25}`, { cwd: targetDir });
        break;
      default:
        await execAsync2(`npm install ${spec25} --prefix "${targetDir}"`);
    }
    onProgress?.({
      phase: "installing-deps",
      message: `${pm} install complete.`
    });
