        await execAsync2(`git clone --branch "${branch}" --single-branch --depth 1 "${info.gitUrl}" "${tempDir}"`, {
          env: { ...process.env, GIT_TERMINAL_PROMPT: "0" }
        });
        onProgress?.({
          phase: "installing-deps",
          message: "Installing dependencies..."
        });
        const pm2 = await detectPackageManager();
