function countSharedConversationWindows(messages, leftEntityId, rightEntityId, windowMs = 1000 * 60 * 60) {
  const relevantMessages = messages.filter((message) => (message.entityId === leftEntityId || message.entityId === rightEntityId) && toMessageTimestamp(message.createdAt) !== null).sort((left, right) => (toMessageTimestamp(left.createdAt) ?? 0) - (toMessageTimestamp(right.createdAt) ?? 0));
  if (relevantMessages.length < 2) {
    return 0;
  }
  const rooms = new Map;
  for (const message of relevantMessages) {
    const roomKey = typeof message.roomId === "string" ? message.roomId : "__shared__";
    if (!rooms.has(roomKey)) {
      rooms.set(roomKey, []);
    }
    rooms.get(roomKey)?.push(message);
  }
  let windowCount = 0;
  for (const roomMessages of rooms.values()) {
    let currentWindowStart = null;
    let seenLeft = false;
    let seenRight = false;
    const flushWindow = () => {
      if (seenLeft && seenRight) {
        windowCount += 1;
      }
      currentWindowStart = null;
      seenLeft = false;
      seenRight = false;
    };
    for (const message of roomMessages) {
      const createdAt = toMessageTimestamp(message.createdAt);
      if (createdAt === null) {
        continue;
      }
      if (currentWindowStart === null || createdAt - currentWindowStart > windowMs) {
        if (currentWindowStart !== null) {
          flushWindow();
        }
        currentWindowStart = createdAt;
      }
      if (message.entityId === leftEntityId) {
        seenLeft = true;
      }
      if (message.entityId === rightEntityId) {
        seenRight = true;
      }
    }
    if (currentWindowStart !== null) {
      flushWindow();
    }
  }
  return windowCount;
}

