  async ensureAgentExists(agent2) {
    if (!agent2.id) {
      throw new Error("Agent id is required");
    }
    const existingAgent = (await this.adapter.getAgentsByIds([agent2.id]))[0] ?? null;
    let agentToUpsert;
    if (existingAgent) {
      const mergedSettings = {
        ...existingAgent.settings,
        ...agent2.settings
      };
      const existingSecrets = existingAgent.secrets && typeof existingAgent.secrets === "object" ? existingAgent.secrets : {};
      const existingSettingsSecrets = existingAgent.settings?.secrets && typeof existingAgent.settings.secrets === "object" ? existingAgent.settings.secrets : {};
      const agentSecrets = agent2.secrets && typeof agent2.secrets === "object" ? agent2.secrets : {};
      const agentSettingsSecrets = agent2.settings?.secrets && typeof agent2.settings.secrets === "object" ? agent2.settings.secrets : {};
      const mergedSecrets = {
        ...existingSecrets,
        ...existingSettingsSecrets,
        ...agentSecrets,
        ...agentSettingsSecrets
      };
      if (Object.keys(mergedSecrets).length > 0) {
        mergedSettings.secrets = mergedSecrets;
      }
      agentToUpsert = {
        ...existingAgent,
        ...agent2,
        settings: mergedSettings,
        id: agent2.id,
        updatedAt: Date.now(),
        secrets: Object.keys(mergedSecrets).length > 0 ? mergedSecrets : agent2.secrets
      };
    } else {
      agentToUpsert = {
        ...agent2,
        id: agent2.id,
        createdAt: Date.now(),
        updatedAt: Date.now()
      };
    }
    await this.adapter.upsertAgents([agentToUpsert]);
    const refreshedAgent = (await this.adapter.getAgentsByIds([agent2.id]))[0] ?? null;
    if (!refreshedAgent) {
      throw new Error(`Failed to retrieve agent after upsert: ${agent2.id}`);
    }
    this.logger.debug({ src: "agent", agentId: agent2.id }, existingAgent ? "Agent updated on restart" : "Agent created");
    return refreshedAgent;
  }
