  "Helps",
  "Allows",
  "Should",
  "Provides",
  "Retrieves",
  "Returns",
  "Generates",
  "Creates",
  "Updates",
  "Deletes",
  "Sends",
  "Extracts",
  "Identifies",
  "Summarizes",
  "Compresses",
